  hu = `Wpisz pełny adres URL wydarzenia, a następnie wybierz z menu autouzupełniania. Wydarzenie musi być publicznie widoczne, by mogło zostać dodane.`,
  gu = `Podaj wydarzenie dalej`,
  _u = `Podaj dalej`,
  vu = `Podanie dalej to odwołanie się do wydarzenia w centrum aktualności na osi czasu wybranych poniżej grup. Są to inne grupy społeczności lub aplikacje, w których obrębie to wydarzenie może zostać podane dalej. Wybierz przynajmniej jedną grupę, do której chcesz podać dalej.`,
