  ku = `Przytoczona zawartość: %2$s.`,
  Au = `Przed opublikowaniem tej strony wymagane jest otrzymanie jej oceny od Valve`,
  ju = `To wydarzenie wyprzedażowe oczekuje na zatwierdzenie przez Valve`,
  Mu = `Użyj przycisku po prawej na co najmniej 7 dni przed twoją pożądaną datą publikacji, by przesłać swoją stronę do oceny oraz by upewnić się, że wystarczy czasu na dokonanie oceny, zatwierdzenie strony i wprowadzenie wszelkich koniecznych zmian.`,
  Nu = `Zespół Steam skontaktuje się z tobą za pośrednictwem zgłoszenia do Pomocy technicznej Steamworks, jeśli będą wymagane jakiekolwiek zmiany na twojej stronie. Możesz wyświetlić zgłoszenie do Pomocy technicznej Steamworks i w razie konieczności dodać komentarze, klikając przycisk po prawej.`,
  Pu = `Oznaczenie strony jako zatwierdzonej pozwoli partnerowi opublikować wyprzedaż i udostępnić ją użytkownikom.`,
  Fu = `Poproś o ocenę…`,
  Iu = `Poproś o ocenę`,
  Lu = `Tworzy zgłoszenie z prośbą o ocenę strony wyprzedaży w celu uzyskania pozwolenia na publikację. Skorzystaj z tego, gdy twoja strona wyprzedaży będzie miała już ostateczne grafiki i zawierała wszystkie gry, które chcesz wyróżnić.`,
  Ru = `To działanie spowoduje utworzenie zgłoszenia do Pomocy technicznej Steamworks zawierającego prośbę o ocenę twojej strony wyprzedaży przez Valve. Działanie to powinno zostać wykonane tylko wtedy, gdy twoje grafiki i komunikaty przyjmą ostateczną wersję, a lista gier będzie kompletna.`,
  zu = `Upewnij się, że tytuł i cel twojego wydarzenia są jasno opisane blisko góry strony. W przypadku pokazów jest możliwe, że będziesz potrzebował sekcji z tekstem na górze strony, by opisać, czym jest twój pokaz i jak on działa.`,
  Bu = `Strona wyprzedaży zostanie zablokowana po poddaniu jej ocenie. Jeśli potrzebujesz wprowadzić zmiany po zakończeniu oceny lub po rozpoczęciu wydarzenia, napisz w komentarzu, z czym wiążą się te zmiany i dlaczego nie mogły zostać ukończone przed oceną.`,
  Vu = `Opcjonalne: informacje, które chcesz przesłać do recenzentów.`,
  Hu = `Wybierz partnerów, których członkowie również mogą uzyskać dostęp do zgłoszenia z prośbą.`,
  Uu = `Opcjonalne: Jeśli wybierzesz tę opcję, inni członkowie partnerów będą mieć dostęp i będą mogli udzielić odpowiedzi na zgłoszenie. Domyślnie tylko ty możesz czytać, aktualizować i odpowiadać na utworzone zgłoszenie.`,
  Wu = `Nie udało się utworzyć zgłoszenia. Spróbuj ponownie później.`,
  Gu = `Nie udało się utworzyć nowego zgłoszenia. Zgłoszenie tego rodzaju już istnieje. Ukończ proces oceny twojej innej strony wyprzedaży przed przesłaniem tej albo zaktualizuj istniejące zgłoszenie, by zawierało ono ocenę także tej strony.`,
  Ku = `Pomyślnie utworzono zgłoszenie!`,
  qu = `Zobacz zgłoszenie dotyczące oceny…`,
