  rB = `To wydarzenie zewnętrzne jest organizowane przez %1$s`,
  iB = `To wydarzenie zewnętrzne jest organizowane przez %1$s i %2$s`,
  aB = `Organizator musi podać, kto z zewnątrz organizuje to wydarzenie.`,
  oB = `Gdy ta opcja jest włączona, organizatorzy muszą określić, kto jest gospodarzem wydarzenia, tak by zapobiec złudnemu wrażeniu, że to Valve jest gospodarzem. Informacja ta jest wyświetlana na stronie wyprzedaży widocznej dla klientów.`,
  sB = `Wyczyść wszystkich wprowadzonych organizatorów wydarzenia`,
