  IB = `Podgląd dynamicznego ujawniania`,
  LB = `Poniższa sekcja posiada włączoną funkcję dynamicznego ujawniania. Możesz sprawdzić podgląd jej działania, uruchamiając test. Jego rezultat zostanie zresetowany po opuszczeniu zakładki podglądu.`,
  RB = `Uruchom tryb testowy`,
  zB = `Wyczyściliśmy oryginalne dane i ujawnimy wszystkie wpisy losowo. Odświeży się automatycznie za %1$s s.`,
  BB = `Wymuś wywołanie usługi`,
