  HB = `Działa na tym komputerze dzięki`,
  UB = `Steam Play.`,
  WB = `wybrany przez ciebie dla tego produktu.`,
  GB = `wybrane przez ciebie dla wszystkich produktów.`,
  KB = `wybrane przez Valve w ramach testów.`,
  qB = `Działa na tym komputerze dzięki <1>Steam Play</1>.`,
  JB = `%1$s wybrany przez ciebie dla tego tytułu.`,
  YB = `%1$s wybrane przez Valve w ramach testów.`,
  XB = `Nagrody Steam`,
  ZB = `Nagród Steam`,
  QB = `Nominowana do Nagród Steam`,
  $B = `Nominuj już teraz. Głosuj w grudniu.`,
  eV = `Nagrody Steam tego wydarzenia zakończyły się. Wróć podczas tegorocznej jesiennej i zimowej wyprzedaży, by wziąć udział w corocznych Nagrodach Steam!`,
  tV = `Grudzień %1$s`,
  nV = `Kliknij poniżej, by zagłosować na %1$s:`,
  rV = `Twórcy gry %1$s chcieliby otrzymać od ciebie nominację w poniższej kategorii.`,
  iV = `Kliknij tutaj, by nominować %1$s w kategorii na stronie Nagród Steam.`,
  aV = `Nominacje zostały zakończone. Zagłosuj podczas zimowej wyprzedaży. Zwycięzcy zostaną ogłoszeni 2 stycznia.`,
  oV = `Głosowanie na Nagrody Steam dobiegło końca. Kliknij tutaj, aby zobaczyć wyniki.`,
  sV = `Nominuj do:`,
  cV = `Zobacz swoje nominacje`,
  lV = `Nominuj tę grę w kategorii %1$s.`,
  uV = `Twoja nominacja dla tej gry w kategorii %1$s została przesłana.`,
  dV = `Gra roku`,
  fV = `Gra VR roku`,
  pV = `Owoc miłości`,
  mV = `Razem raźniej`,
  hV = `Znakomity styl wizualny`,
  gV = `Najbardziej innowacyjna rozgrywka`,
  _V = `Najlepsza gra, w której jesteś do bani`,
  vV = `Najlepsza ścieżka dźwiękowa`,
  yV = `Gra ze znakomitą fabułą`,
  bV = `Usiądź i zrelaksuj się`,
  xV = `Nie sugeruj konkretnej kategorii i pozwól swoim fanom wybrać taką kategorię, która ich zdaniem najlepiej pasuje do twojej gry. Wydarzenie wciąż będzie zawierać link do strony nominacji.`,
  SV = `Bez kategorii`,
  CV = `Może to zasługa wciągającej rozgrywki, trzymającej w napięciu historii, dobrze napisanych postaci, nieskazitelnej wizji całości czy też uzależniającego trybu wieloosobowego. Niezależnie od powodu, zwycięzca w kategorii gry roku 2020 stał się klasykiem już w momencie wydania.`,
  wV = `Gra VR roku nie udaje jedynie zwykłej rzeczywistości. Ta gra ulepsza rzeczywistość, wykorzystując medium, jakim jest VR, i popycha granice wirtualnego świata.`,
  TV = `Z tej gierki żadna nowość, a członkowie zespołu stojącego za nią już od dawna nie myślą o debiucie swojego dziecka. Ale że rodzice z nich na medal, to wciąż je wspierają, wydając aktualizacje z nową zawartością po tych wszystkich latach.`,
  EV = `Istnieją gry, które po prostu nie są takie same, gdy gra się w nie w pojedynkę. Może potrzebujesz znajomego, który osłoni ci plecy. Może potrzebujesz znajomego, by wbić mu nóż w plecy. Tak czy inaczej, uciecha czeka na tych, którzy zbiorą znajomych, by zagrać w te gry.`,
  DV = `Styl wizualny nie aspiruje do odwzorowywania wyglądu świata rzeczywistego (chociaż to samo w sobie jest bardzo szlachetne)… on opisuje charakterystyczny wygląd i atmosferę, którymi gra wręcz ocieka.`,
  OV = `Projektanci tej gry przodują w kreatywnym eksperymentowaniu, rzucając nowe światło na rozgrywkę i używając oszałamiających niespodzianek. Ta gra zachwyciła, zainspirowała i zabawiła nowością, której nigdy wcześniej nie było ci dane doświadczyć.`,
  kV = `Jest to gra, która nagradza uporczywość i nie jest dla ludzi o słabych nerwach. Jest to najtrudniejsza gra, jaką obdarzyliśmy miłością.`,
  AV = `Ten niedoceniony bohater zasługuje na uznanie za swoją wybitną ścieżkę dźwiękową. W to mi graj! `,
  jV = `Czasami w czuły punkt może trafić tylko gra stawiająca mocno na fabułę, a ta jest niczym koński kopniak. Trzyma w napięciu jak telenowela i jest tak dopracowana jak scenariusz wysokobudżetowego serialu. Należą się brawa za to, że dzięki tobie coś odczuwamy!`,
  MV = `Ta gra to antidotum na ciężki dzień. Jest spokojna, relaksująca i sprawi, że twoje zmartwienia rozpłyną się bez śladu. To twój czas na osiągnięcie zen.`,
  NV = `Zmienić twoją nominację?`,
  PV = `Możesz nominować tylko jedną grę w każdej kategorii, a dla tej twoją nominacją jest już %1$s. Czy chcesz zamiast tego nominować %2$s?`,
  FV = `Głosuj`,
  IV = `Zagłosowano`,
  LV = `Oddano głos`,
  RV = `Zmienić twój wybór?`,
  zV = `Możesz głosować tylko na jedną grę w każdej kategorii, a już wybrałeś następującą grę: %1$s. Czy chcesz zamiast tego wybrać: %2$s?`,
  BV = `Wygląda na to, że twoje konto jest ograniczone. Aby zapobiegać nadużyciom w nominowaniu, musisz wydać przynajmniej 5 dolarów amerykańskich na Steam, by móc wziąć udział w Nagrodach Steam. %1$s, by dowiedzieć się więcej.`,
  VV = `Wygląda na to, że twoje konto jest ograniczone. Aby zapobiegać nadużyciom w głosowaniu, musisz wydać przynajmniej 5 dolarów amerykańskich na Steam, by móc wziąć udział w Nagrodach Steam. %1$s, by dowiedzieć się więcej.`,
