  SH = `Istnieją gry, które po prostu nie są takie same, gdy gra się w nie w pojedynkę. Może potrzebujesz znajomego, który osłoni ci plecy. Może potrzebujesz znajomego, by wbić mu nóż w plecy. Tak czy inaczej, uciecha czeka na tych, którzy zbiorą znajomych, by zagrać w te gry.`,
  CH = `Styl wizualny nie aspiruje do odwzorowywania wyglądu świata rzeczywistego (chociaż to samo w sobie jest bardzo szlachetne)… on opisuje charakterystyczny wygląd i atmosferę, którymi gra wręcz ocieka.`,
  wH = `Projektanci tej gry przodują w kreatywnym eksperymentowaniu, rzucając nowe światło na rozgrywkę i używając oszałamiających niespodzianek. Ta gra zachwyciła, zainspirowała i zabawiła nowością, której nigdy wcześniej nie było ci dane doświadczyć.`,
