  EH = `Ten niedoceniony bohater zasługuje na uznanie za swoją wybitną ścieżkę dźwiękową. W to mi graj! `,
  DH = `Czasami w czuły punkt może trafić tylko gra stawiająca mocno na fabułę, a ta jest niczym koński kopniak. Trzyma w napięciu jak telenowela i jest tak dopracowana jak scenariusz wysokobudżetowego serialu. Tej grze należą się brawa za to, że dzięki niej coś odczuwamy!`,
  OH = `Ta gra to antidotum na ciężki dzień. Jest spokojna, relaksująca i sprawi, że twoje zmartwienia rozpłyną się bez śladu. To twój czas na osiągnięcie zen.`,
  kH = `Ta gra była tak dobra, że nie sposób ci się było z nią rozstać, więc towarzyszyła ci wszędzie. Na szczęście wszystko to, co uczyniło ją grywalną bez ograniczeń na stacjonarnym sprzęcie, stało się jeszcze lepsze po odejściu od niego.`,
  AH = `Tylko VR`,
  jH = `Obsługa VR`,
  MH = `Do następnego losowania pozostało %1$s!`,
  NH = `Czas pozostały do następnego losowania.`,
  PH = `Oglądaj dalej, by uzyskać szansę na wygraną!`,
  FH = `Losowanie w toku`,
  IH = `Liczba dotychczasowych zwycięzców!`,
  LH = `Loteria dobiegła końca. Dziękujemy za udział.`,
  RH = `Loteria dobiegła końca, a nagrody przyznaliśmy %1$s szczęśliwym zwycięzcom. Dziękujemy za udział.`,
  zH = `Kliknij tutaj, aby dowiedzieć się więcej na temat nagród, zwycięzców i zasad`,
  BH = `Wróć każdego dnia po nowy prezent od cesarza!`,
  VH = `Wróć każdego dnia po nowy rozdział`,
  HH = `Pierwszy prezent`,
  UH = `Drugi prezent`,
  WH = `Trzeci prezent`,
  GH = `Czwarty prezent`,
  KH = `otwarto`,
  qH = `pokaż historię`,
  JH = `otwórz teraz`,
  YH = `otwórz następny`,
  XH = `otwórz %1$s`,
  ZH = `Użyj przeglądarki, która wspiera wideo HTML, by otworzyć swoją kopertę.`,
  QH = `Wróć do wyprzedaży`,
  $H = `Odwiedź ryneczek`,
  eU = `Otrzymano %1$s szt. żetonów`,
  tU = `Twoje saldo`,
  nU = `%1$s szt. żetonów`,
  rU = `Nie udało się otworzyć koperty`,
  iU = `WIELKI WYŚCIG CESARZA`,
  aU = `Geneza powstania znaków chińskiego zodiaku`,
  oU = `Część I z IV`,
  sU = `Część II z IV`,
  cU = `Część III z IV`,
  lU = `Część IV z IV`,
  uU = `Nefrytowy Cesarz wezwał wszystkie stworzenia w swoim cesarstwie do wyścigu do niebiańskiego pałacu, obiecując pierwszym dwunastu miejsce w swoim w nowym kalendarzu.

Pomysłowy Szczur był pierwszym, który dotarł do boskiej krainy. Jako że nie przepadał za pływaniem, przeprawił się na drugą stronę rzeki na grzbiecie godnego zaufania Bawołu. Kiedy obaj zbliżali się do brzegu, Szczur prędko zeskoczył z Bawołu, by dotrzeć do ogrodu cesarza przed nim.

Opanowany Bawół przeprawił się przez rzekę bez najmniejszego problemu. Zwycięstwo w wyścigu nie miało dla niego większego znaczenia, więc cieszył się, że pomógł Szczurowi dotrzeć na metę jako pierwszy.`,
  dU = `Tygrys, który bardzo cenił sobie samodzielność, stawiał kroki ze zbyt wielką rozwagą, sądząc, że lepiej jest dotrzeć do mety jako trzeci, niż nie dotrzeć wcale. Nie miał więc szansy, by przegonić Bawołu.

Poruszający się ze zwinnością Królik wskoczył na kłodę, która unosiła się nieśpiesznie i bez celu na wodzie. Nie najlepszy był z niego strateg, ale za to dopisało mu szczęście – nagle pojawił się pomocny wiatr, dzięki któremu jego prowizoryczna łódka ruszyła prędko w odpowiednim kierunku.

Latający Smok, unosząc się w powietrzu, dostrzegł wioskę, której mieszkańcy potrzebowali pomocy – pośpieszył więc im na ratunek. Pomógł też Królikowi, tworząc wietrzyk, który pchnął jego łódkę wraz z prądem rzeki. Smok znacznie wyżej cenił sobie honor niż zwycięstwo, więc dotarł na miejsce piąty.`,
  fU = `Podstępnego z natury Węża mało interesował długotrwały wysiłek, więc ukradkiem owinął się wokół kopyta Konia.

Kiedy Koń galopował w stronę mety, Wąż zsunął się mu z kopyta. Na dłuższą chwilę wprawił Konia w osłupienie, tak że udało się mu dotrzeć na metę jako szósty. Po chwili na metę przybył kłusem płochliwy Koń.`,
  pU = `Koza, Małpa i Kogut postawili na pracę zespołową. Ósme miejsce przyznano Kozie, jako że odegrała kluczową rolę w przeprawie. Dziarska Małpa dotarła kolejna, a za nią, na dziesiątym miejscu, kroczący z dostojeństwem Kogut, dumny z faktu, że miejsca rozdysponowano sprawiedliwie.

Skorego do zabawy Psa najbardziej zaprzątało pluskanie się w wodzie – uznał jedenaste miejsce za uczciwe, jeśli wziąć pod uwagę wszystkie chwile spędzone na zabawie.

Ostatnia dotarła na metę Świnia, która zrobiła sobie przerwę na przekąskę i drzemkę, dobrze wiedząc, że każde ze zwierząt otrzyma szansę, by spędzić chwilę u boku cesarza.`,
  mU = `Zmiany w profilu zostaną zastosowane po ocenie`,
  hU = `© %1$s Valve Corporation. Wszelkie prawa zastrzeżone. Wszystkie znaki handlowe są własnością ich prawnych właścicieli w Stanach Zjednoczonych i innych krajach.`,
  gU = `Wybierz abonament`,
  _U = `Twój obecny abonament`,
  vU = `Jesteś już członkiem`,
  yU = `Zaoszczędź %2$s`,
